<script setup lang="ts">import{ref,computed,onMounted}from 'vue';import{useRoute}from 'vue-router';import{chains,loadChain}from '../stores/chains';import{recomputeChain,refreshChainSample,replaceChainTarget,publishChain,getPublication}from '../api/chains';import{getTargets}from '../api/batches';
import{canEdit,isAdmin}from '../stores/auth';import{useTask}from '../hooks/useTask';import{usePolling}from '../hooks/usePolling';import{chainStatusLabels,statusLabels,coverageLabels,dimensionLabels}from '../constants/enums';import{number,dateTime}from '../utils/format';
import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import EmptyState from '../components/common/EmptyState.vue';
const route=useRoute();const id=computed(()=>Number(route.params.id));const{error,busy,execute}=useTask();
const note=ref('整组链段已通过收敛与分解对账，按当前冻结口径原子发布。');
const targetDraft=ref<{dimension:string;category:string;population:number}[]>([]);const showTarget=ref(false);
const currentSegments=computed(()=>(chains.selected?.segments||[]).filter(s=>s.version===chains.selected?.version));
const refresh=()=>execute(async()=>{await loadChain(id.value)});
onMounted(refresh);
usePolling(()=>{if(chains.selected?.status==='recomputing')refresh()});
const retry=()=>execute(async()=>{await recomputeChain(id.value);await refresh()});
const correctSample=(nodeId:number)=>execute(async()=>{await refreshChainSample(id.value,nodeId);await refresh()});
const openTargets=async()=>execute(async()=>{showTarget.value=true;const node=chains.selected?.nodes[0];if(node)targetDraft.value=await getTargets(node.batch_id)});
const saveTarget=()=>execute(async()=>{await replaceChainTarget(id.value,targetDraft.value);showTarget.value=false;await refresh()});
const publish=()=>execute(async()=>{await publishChain(id.value,note.value);await refresh()});
const downloadPublication=async(pubId:number)=>execute(async()=>{const pub=await getPublication(pubId);const blob=new Blob([JSON.stringify(pub.snapshot,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`chain-${id.value}-v${pub.version}.json`;a.click();URL.revokeObjectURL(url)});
const fmt=(v:number|null|undefined,d=2)=>v===null||v===undefined?'—':number(v,d);
</script><template><PageHeading index="05" title="链式比较底稿" subtitle="冻结口径下的逐月校准、相邻月份分解对账与整组原子发布。"/><ErrorNotice :message="error" @retry="refresh"/><template v-if="chains.selected"><div class="section-heading"><h2>{{chains.selected.name}} <small>v{{chains.selected.version}} · {{chainStatusLabels[chains.selected.status]||chains.selected.status}}</small></h2><span v-if="chains.selected.published_version">已发布 v{{chains.selected.published_version}}</span></div><p v-if="chains.selected.last_error" class="error">{{chains.selected.last_error}} <button type="button" @click="retry">同版本重试 ↻</button></p><p v-if="chains.selected.status==='recomputing'" class="empty">链段正在后台重算；本页自动刷新，已发布版本继续可读。</p><p class="method-note">{{chains.selected.description}} ｜ 共同目标 SHA256：<span class="mono">{{chains.selected.target_checksum.slice(0,16)}}…</span>（epoch {{chains.selected.target_epoch}}）</p><div class="form-actions" v-if="canEdit"><button :disabled="busy||chains.selected.status==='recomputing'" @click="retry">重投当前版本</button><button v-if="isAdmin" :disabled="busy||chains.selected.status==='recomputing'" @click="openTargets">更正共同目标</button></div><form v-if="showTarget&&isAdmin" class="import-form" @submit.prevent="saveTarget"><h2>登记新的共同目标（全链将进入下一版本）</h2><div class="table-wrap"><table><thead><tr><th>维度</th><th>类别</th><th>目标人数</th></tr></thead><tbody><tr v-for="(t,i) in targetDraft" :key="t.dimension+t.category"><td>{{dimensionLabels[t.dimension]}}</td><td>{{t.category}}</td><td><input v-model.number="targetDraft[i].population" type="number" min="0" step=".01" required/></td></tr></tbody></table></div><div class="form-actions"><button class="primary" :disabled="busy">校验并推进目标版本 →</button><button type="button" @click="showTarget=false">取消</button></div></form><div class="section-heading"><h2>链节点 / 依赖与样本更正</h2><span>校准复用键 = 样本快照 × 共同目标 × 参数 的 SHA256</span></div><div class="chain-nodes"><article v-for="n in chains.selected.nodes" :key="n.id" class="chain-node"><header><b>{{n.month_label}}</b><span class="badge" :class="n.status">{{statusLabels[n.status]||n.status}}</span></header><p>{{n.batch?.name}}<small>{{n.batch?.code}} · {{n.calibration?.sample_count||0}} 条冻结样本 · epoch {{n.sample_epoch}}</small></p><dl v-if="n.calibration"><div><dt>加权均值</dt><dd>{{fmt(n.calibration.weighted_mean)}} 分钟</dd></div><div><dt>有效样本</dt><dd>{{fmt(n.calibration.effective_sample_size,1)}}</dd></div><div><dt>收敛</dt><dd>{{n.calibration.converged?'已收敛':'未收敛'}}</dd></div></dl><p v-if="n.error" class="error">{{n.error}}</p><details><summary>查看依赖与校验和</summary><ul class="deps"><li>样本 epoch {{n.depends_on.sample.epoch}}：<span class="mono">{{n.depends_on.sample.checksum.slice(0,20)}}…</span></li><li>目标 epoch {{n.depends_on.target.epoch}}：<span class="mono">{{n.depends_on.target.checksum.slice(0,20)}}…</span></li><li>参数 容差{{n.depends_on.params.tolerance}} / {{n.depends_on.params.max_iterations}}次 / 截断{{n.depends_on.params.cap_ratio}}倍</li><li>校准 checksum：<span class="mono">{{n.depends_on.calibration_checksum?.slice(0,24)||'—'}}…</span></li></ul></details><button v-if="canEdit" :disabled="busy||chains.selected.status==='recomputing'" @click="correctSample(n.id)">从实时批次拉取样本更正 →</button></article></div><div class="section-heading"><h2>相邻月份分解（工作版本 v{{chains.selected.version}}）</h2><span>恒等式：总变化 ≡ 构成效应 + 时长效应</span></div><div class="table-wrap"><table><thead><tr><th>链段</th><th>状态</th><th>均值变化</th><th>样本构成效应</th><th>时长效应</th><th>对账残差</th><th>格覆盖（共/新/失）</th></tr></thead><tbody><tr v-for="s in currentSegments" :key="s.id"><td><strong>{{s.from_label}} → {{s.to_label}}</strong><small v-if="s.result">{{fmt(s.result.weighted_mean_from)}} → {{fmt(s.result.weighted_mean_to)}} 分钟</small></td><td><span class="badge" :class="s.status">{{statusLabels[s.status]||s.status}}</span></td><td v-if="s.result" :class="s.result.total_change>=0?'pos':'neg'">{{fmt(s.result.total_change,3)}}</td><td v-if="s.result">{{fmt(s.result.composition_effect,3)}}</td><td v-if="s.result">{{fmt(s.result.duration_effect,3)}}</td><td v-if="s.result"><span :class="s.result.reconciled?'ok':'bad'">{{fmt(s.result.reconciliation_residual,6)}}</span></td><td v-if="s.result">{{s.result.coverage.common}} / {{s.result.coverage.new}} / {{s.result.coverage.lost}}</td><td v-if="!s.result" colspan="5" class="muted">{{s.error||'等待重算'}}</td></tr></tbody></table></div><details v-for="s in currentSegments.filter(x=>x.result)" :key="'cells-'+s.id" class="cell-detail"><summary>逐格分解明细 / {{s.from_label}} → {{s.to_label}}</summary><div class="table-wrap"><table><thead><tr><th>分区</th><th>年龄组</th><th>方式</th><th>覆盖</th><th>份额 前→后</th><th>格均时长 前→后</th><th>构成效应</th><th>时长效应</th></tr></thead><tbody><tr v-for="c in s.result!.cells" :key="c.zone+c.age_band+c.mode"><td>{{c.zone}}</td><td>{{c.age_band}}</td><td>{{c.mode}}</td><td>{{coverageLabels[c.coverage]||c.coverage}}</td><td>{{fmt(c.share_from,4)}} → {{fmt(c.share_to,4)}}</td><td>{{fmt(c.mean_minutes_from)}} → {{fmt(c.mean_minutes_to)}}</td><td>{{fmt(c.composition_effect,3)}}</td><td>{{fmt(c.duration_effect,3)}}</td></tr></tbody></table></div></details><form v-if="isAdmin" class="review-form" @submit.prevent="publish"><h2>整组原子发布</h2><label>发布说明<textarea v-model="note" rows="3" minlength="4" maxlength="500" required/></label><button class="primary" :disabled="busy||chains.selected.status!=='ready'">发布整组 v{{chains.selected.version}} →</button><p v-if="chains.selected.status!=='ready'" class="method-note">整组链段未全部就绪前不能发布；已发布版本仍在下方保留。</p></form><div class="section-heading"><h2>已发布版本（不可变）</h2></div><EmptyState v-if="!chains.selected.publications.length" title="还没有发布记录" hint="整组收敛且对账通过后，由负责人原子发布。"/><div v-else class="pub-list"><article v-for="p in chains.selected.publications" :key="p.id"><b>v{{p.version}}</b><p>{{p.note}}</p><small>{{dateTime(p.created_at)}} · checksum <span class="mono">{{p.checksum.slice(0,20)}}…</span></small><button @click="downloadPublication(p.id)">下载发布快照 JSON ↓</button></article></div></template>
</template>
